-- TMS FNC UI Pack - Theming Dashboard demo: the order management sample database.
-- Generated by make_orders_db.py (TMS FNC Theming harness); rebuild with: sqlite3 orders.db < orders.sql

CREATE TABLE customers (
  name    VARCHAR(60) NOT NULL PRIMARY KEY,
  region  VARCHAR(20) NOT NULL,
  contact VARCHAR(60) NOT NULL
);

-- id is the order number (#10240, ...); a new order gets the next one
CREATE TABLE orders (
  id         INTEGER PRIMARY KEY,
  customer   VARCHAR(60) NOT NULL,
  order_date DATE NOT NULL,
  amount     DOUBLE NOT NULL DEFAULT 0,
  status     VARCHAR(12) NOT NULL DEFAULT 'Open' CHECK (status IN ('Open', 'Packing', 'Shipped', 'Late')),
  fulfilment INT NOT NULL DEFAULT 0 CHECK (fulfilment BETWEEN 0 AND 100),
  express    BOOLEAN NOT NULL DEFAULT 0
);
CREATE INDEX orders_date ON orders (order_date);

-- the projects card: projects (parent_id NULL) and their tasks; a project's status follows its tasks
CREATE TABLE projects (
  id        INTEGER PRIMARY KEY,
  parent_id INT REFERENCES projects (id),
  name      VARCHAR(60) NOT NULL,
  owner     VARCHAR(30) NOT NULL,
  status    VARCHAR(12),
  done      BOOLEAN NOT NULL DEFAULT 0
);

-- the quarterly goals card: metric revenue (target in dollars), on_time and retention (percent)
CREATE TABLE goals (
  id     INTEGER PRIMARY KEY,
  name   VARCHAR(40) NOT NULL,
  metric VARCHAR(12) NOT NULL,
  target DOUBLE NOT NULL
);

BEGIN TRANSACTION;





COMMIT;
